package io.coolbox.finance;
import com.sun.jna.Pointer;import com.sun.jna.ptr.DoubleByReference;import io.coolbox.internal.ErrorBuffer;import io.coolbox.internal.Matrices;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.util.function.ToDoubleFunction;
/** Python {@code finance} pricing and stochastic-process helpers. */
public final class Finance {private static final OptFinanceNative N=OptFinanceNative.INSTANCE;private static final AtomicLong IDS=new AtomicLong(50000);private static final ConcurrentHashMap<Long,ToDoubleFunction<double[]>> CALLBACKS=new ConcurrentHashMap<>();private Finance(){}public static double evaluate(Formula f,double... values){ErrorBuffer e=new ErrorBuffer();double v=N.coolbox_finance_formula(f.ordinal(),values,values.length,e.pointer(),e.capacity());e.throwIfSet();return v;}public static double[] brownianMotionPath(double[] times,double[] shocks,double initial){if(times.length!=shocks.length)throw new IllegalArgumentException("time steps and shocks must match");double[] out=new double[times.length+1];ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_finance_path(0,initial,0,0,times,times.length,shocks,out,e.pointer(),e.capacity()));return out;}public static double[] brownianMotionPath(double[] times,double[] shocks){return brownianMotionPath(times,shocks,0);}public static double[] geometricBrownianMotionPath(double initial,double drift,double volatility,double[] times,double[] shocks){if(times.length!=shocks.length)throw new IllegalArgumentException("time steps and shocks must match");double[] out=new double[times.length+1];ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_finance_path(1,initial,drift,volatility,times,times.length,shocks,out,e.pointer(),e.capacity()));return out;}public static double itoIntegralLeftPoint(double[] values,double[] increments){return ito(0,values,increments);}public static double itoIsometryVariance(double[] values,double[] times){return ito(1,values,times);}private static double ito(int op,double[] v,double[] inc){if(v.length!=inc.length)throw new IllegalArgumentException("input sizes differ");DoubleByReference out=new DoubleByReference();ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_finance_ito(op,v,inc,v.length,out,e.pointer(),e.capacity()));return out.getValue();}private static double[] flatten(double[][] p,int steps){double[] a=new double[p.length*steps];for(int i=0;i<p.length;i++){if(p[i].length!=steps)throw new IllegalArgumentException("each shock path must match time steps");System.arraycopy(p[i],0,a,i*steps,steps);}return a;}public static MonteCarloEstimate monteCarloEstimate(MonteCarloContract contract,double spot,double strike,double barrier,double rate,double volatility,double[] times,double[][] shocks,double confidence){MonteCarloEstimate out=new MonteCarloEstimate();ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_finance_monte_carlo(contract.ordinal(),spot,strike,barrier,rate,volatility,times,times.length,flatten(shocks,times.length),shocks.length,confidence,.01,.01,out,e.pointer(),e.capacity()));out.read();return out;}public static MonteCarloGreeks monteCarloGreeksFd(MonteCarloGreekContract contract,double spot,double strike,double barrier,double rate,double volatility,double[] times,double[][] shocks,double confidence,double relativeBump,double timeBump){MonteCarloGreeks out=new MonteCarloGreeks();ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_finance_monte_carlo_greeks(contract.ordinal(),spot,strike,barrier,rate,volatility,times,times.length,flatten(shocks,times.length),shocks.length,confidence,relativeBump,timeBump,out,e.pointer(),e.capacity()));out.read();return out;}public static MonteCarloEstimate monteCarloEstimateCustomPayoff(double spot,double rate,double volatility,double[] times,double[][] shocks,ToDoubleFunction<double[]> payoff,double confidence){long id=IDS.getAndIncrement();CALLBACKS.put(id,payoff);OptFinanceNative.Payoff cb=(user,path,n,out)->{try{out.setValue(CALLBACKS.get(Pointer.nativeValue(user)).applyAsDouble(path.getDoubleArray(0,(int)n)));return 1;}catch(Throwable t){return 0;}};MonteCarloEstimate out=new MonteCarloEstimate();ErrorBuffer e=new ErrorBuffer();try{e.check(N.coolbox_finance_monte_carlo_generic(spot,rate,volatility,times,times.length,flatten(shocks,times.length),shocks.length,confidence,cb,Pointer.createConstant(id),out,e.pointer(),e.capacity()));}finally{CALLBACKS.remove(id);}out.read();return out;}public static MonteCarloGreeks monteCarloGreeksCustomPayoffFd(double spot,double strike,double rate,double volatility,double[] times,double[][] shocks,ToDoubleFunction<double[]> payoff,double confidence,double relativeBump,double timeBump){long id=IDS.getAndIncrement();CALLBACKS.put(id,payoff);OptFinanceNative.Payoff cb=(user,path,n,out)->{try{out.setValue(CALLBACKS.get(Pointer.nativeValue(user)).applyAsDouble(path.getDoubleArray(0,(int)n)));return 1;}catch(Throwable t){return 0;}};MonteCarloGreeks out=new MonteCarloGreeks();ErrorBuffer e=new ErrorBuffer();try{e.check(N.coolbox_finance_monte_carlo_greeks_generic(spot,strike,rate,volatility,times,times.length,flatten(shocks,times.length),shocks.length,confidence,relativeBump,timeBump,cb,Pointer.createConstant(id),out,e.pointer(),e.capacity()));}finally{CALLBACKS.remove(id);}out.read();return out;}}

